  `uuid` varchar(128) DEFAULT NULL COMMENT 'Unique Key: Universally unique identifier for this entity.',
  `pid` int(11) NOT NULL DEFAULT '0' COMMENT 'The comment.cid to which this comment is a reply. If set to 0, this comment is not a reply to an existing comment.',
  `entity_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'The entity_id of the entity to which this comment is a reply.',
