  `homepage` varchar(255) DEFAULT NULL COMMENT 'The comment author’s home page address from the comment form, if user is anonymous, and the ’Anonymous users may/must leave their contact information’ setting is turned on.',
  `langcode` varchar(12) NOT NULL DEFAULT '' COMMENT 'The language.langcode of this comment.',
  PRIMARY KEY (`cid`),
  UNIQUE KEY `uuid` (`uuid`),
  KEY `comment_status_pid` (`pid`,`status`),
  KEY `comment_num_new` (`entity_id`,`entity_type`(32),`field_id`(32),`status`,`created`,`cid`,`thread`),
  KEY `comment_uid` (`uid`),
  KEY `comment_entity_langcode` (`entity_id`,`entity_type`(32),`field_id`(32),`langcode`),
  KEY `comment_created` (`created`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Stores comments and associated data.' AUTO_INCREMENT=1 ;

