  `info` varchar(128) NOT NULL DEFAULT '' COMMENT 'Block description.',
  `revision_id` int(10) unsigned DEFAULT NULL COMMENT 'The current block_custom_revision.revision_id version identifier.',
  `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'The type of this custom block.',
  `changed` int(11) NOT NULL DEFAULT '0' COMMENT 'The Unix timestamp when the custom block was most recently saved.',
  `langcode` varchar(12) NOT NULL DEFAULT '' COMMENT 'The language.langcode of this node.',
  PRIMARY KEY (`id`),
  UNIQUE KEY `info` (`info`),
  UNIQUE KEY `revision_id` (`revision_id`),
  UNIQUE KEY `uuid` (`uuid`),
